('7707329152-snrip', 'Сведения о специальных налоговых режимах, применяемых налогоплательщиками (ИП)', 'xml', '20241025', 'ОДИПСПЕЦРЕЖИМ', '4.01'),
('7707329152-paytax', 'Сведения об уплаченных организацией в календарном году, предшествующем году размещения указанных сведений в информационно-телекоммуникационной сети "Интернет" в соответствии с подпунктом 1 пункта 1.1 статьи 102 Налогового кодекса Российской Федерации, суммах налогов и сборов (по каждому налогу и сбору) без учета сумм налогов (сборов), уплаченных в связи с ввозом товаров на таможенную территорию Евразийского экономического союза, сумм налогов, уплаченных налоговым агентом, о суммах страховых взносов', 'xml', '20180110', 'ОТКРДАННЫЕ4', '4.01'),
('7707329152-debtam', 'Сведения о суммах задолженности по уплате налогов, сборов и страховым взносам, пеням и штрафам в бюджеты бюджетной системы Российской Федерации', 'xml', '20181201', 'ОТКРДАННЫЕ6', '4.01'),
('7707329152-taxoffence', 'Сведения о налоговых правонарушениях и мерах ответственности за их совершение', 'xml', '20181201', 'ОТКРДАННЫЕ7', '4.01'),
('7707329152-revexp', 'Сведения о суммах доходов и расходов по данным бухгалтерской (финансовой) отчетности организации за год, предшествующий году размещения таких сведений на сайте ФНС России', 'xml', '20180110', 'ОТКРДАННЫЕ5', '4.01'),
('7707329152-registerdisqualified', 'Реестр дисквалифицированных лиц', 'csv', '20150624', NULL, NULL),
('7707329152-disqualifiedpersons', 'Юридические лица, в состав исполнительных органов которых входят дисквалифицированные лица', 'csv', '24062015', NULL, NULL),
('7707329152-massleaders', 'Сведения о физических лицах, являющихся руководителями нескольких юридических лиц', 'csv', '24062015', NULL, NULL),
('7707329152-massfounders', 'Сведения о физических лицах, являющихся учредителями (участниками) нескольких юридических лиц', 'csv', '24062015', NULL, NULL),
